// Downloadable PDFs of the Lernzettel (pdf/*.pdf, generated by scripts/build-pdfs.mjs from print.html).
// Since 2.0 per apprenticeship: one PDF for the AP1 (same for all jobs), one for the AP2 of each job
// and the abbreviations of each job; since 2.10.3 also the formula collection of each job.
// Pure functions, no DOM access.

import { AREAS } from './config.js';
import { JOBS, AP1_TITLE, AP1_SECTIONS, AP2_PARTS, jobById } from './curriculum.js';
import { catalogForJob } from './jobCatalog.js';

export const PDF_DIR = './pdf/';
export const PDF_ALL = 'alle';
export const PDF_GLOSSARY = 'abkuerzungen';
export const PDF_AP1 = 'ap1';
export const ap2PdfKey = (job) => `ap2-${job}`;
export const glossaryPdfKey = (job) => `${PDF_GLOSSARY}-${job}`;
export const PDF_FORMULAS = 'formeln';
export const formulasPdfKey = (job) => `${PDF_FORMULAS}-${job}`;

/** Job of an AP2, glossary or formula key („ap2-fisi“, „abkuerzungen-fisi“, „formeln-fisi“), else null. */
export function pdfJob(key) {
  const m = /^(?:ap2|abkuerzungen|formeln)-([a-z]+)$/.exec(String(key ?? ''));
  return m && jobById(m[1]) ? m[1] : null;
}

const isAp2Key = (key) => String(key).startsWith('ap2-') && pdfJob(key) !== null;
/** True for the formula collection PDF of a job (since 2.10.3). */
export const isFormulasKey = (key) => String(key).startsWith(`${PDF_FORMULAS}-`) && pdfJob(key) !== null;
const isGlossaryKey = (key) => key === PDF_GLOSSARY || (String(key).startsWith(`${PDF_GLOSSARY}-`) && pdfJob(key) !== null);

/** File name for a PDF key (AP1, AP2 per job, glossary per job, all notes, area name); null if unknown. */
export function pdfFileName(key) {
  if (key === PDF_ALL) return 'lernzettel-alle.pdf';
  if (key === PDF_AP1) return 'lernzettel-ap1.pdf';
  if (key === PDF_GLOSSARY) return 'abkuerzungen.pdf';
  if (isAp2Key(key)) return `lernzettel-${key}.pdf`;
  if (isGlossaryKey(key) || isFormulasKey(key)) return `${key}.pdf`;
  const area = AREAS.find((a) => a.name === key);
  return area ? `lernzettel-${area.id}.pdf` : null;
}

/** Title of a PDF (cover and link text). */
export function pdfTitle(key) {
  if (key === PDF_AP1) return `AP1 – ${AP1_TITLE}`;
  if (key === PDF_ALL) return 'Alle Lernzettel';
  const job = jobById(pdfJob(key));
  if (job && isAp2Key(key)) return `AP2 ${job.short} – ${job.name}`;
  if (job && isFormulasKey(key)) return `Formelsammlung ${job.short}`;
  if (job) return `Abkürzungen ${job.short}`;
  if (key === PDF_GLOSSARY) return 'Abkürzungsverzeichnis';
  return `Lernzettel ${key}`;
}

/**
 * PDFs in display order. With a job: the job's four PDFs (AP1, AP2, abbreviations, formulas).
 * Without a job: every generated PDF (AP1, then AP2, abbreviations and formulas of all seven jobs).
 */
export function pdfList(job = null) {
  const entry = (key, label) => ({ key, label, file: pdfFileName(key) });
  const info = jobById(job);
  if (info) {
    return [
      entry(PDF_AP1, 'AP1 – alle Lernzettel'),
      entry(ap2PdfKey(info.id), `AP2 ${info.short} – alle Lernzettel`),
      entry(glossaryPdfKey(info.id), `Abkürzungen ${info.short}`),
      entry(formulasPdfKey(info.id), `Formelsammlung ${info.short}`),
    ];
  }
  return [
    entry(PDF_AP1, 'AP1 – alle Lernzettel'),
    ...JOBS.map((j) => entry(ap2PdfKey(j.id), `AP2 ${j.short} – alle Lernzettel`)),
    ...JOBS.map((j) => entry(glossaryPdfKey(j.id), `Abkürzungen ${j.short}`)),
    ...JOBS.map((j) => entry(formulasPdfKey(j.id), `Formelsammlung ${j.short}`)),
  ];
}

/**
 * Notes of a PDF grouped like the app: AP1 catalog areas (PDF_AP1), the AP2 exam parts of a job
 * (ap2-<job>) or subject areas (PDF_ALL, area name). A note appears only once, in its first group.
 * @returns {{ title: string, notes: object[] }[]} groups in order, notes sorted by title
 */
export function pdfSections(catalog, key) {
  const topicsById = new Map((catalog.topics ?? []).map((t) => [t.id, t]));
  const notes = (catalog.notes ?? []).filter((n) => topicsById.has(n.topic));
  let groups;
  if (key === PDF_AP1) groups = AP1_SECTIONS.map((s) => ({ title: s.title, topics: s.topics }));
  else if (isAp2Key(key)) groups = AP2_PARTS[pdfJob(key)].map((p) => ({ title: p.title, topics: p.topics }));
  else {
    groups = AREAS.filter((a) => key === PDF_ALL || a.name === key)
      .map((a) => ({ title: a.name, topics: [...topicsById.values()].filter((t) => t.area === a.name).map((t) => t.id) }));
  }
  const seen = new Set();
  return groups.map((g) => {
    const own = notes.filter((n) => g.topics.includes(n.topic) && !seen.has(n.id))
      .sort((a, b) => a.title.localeCompare(b.title, 'de'));
    for (const n of own) seen.add(n.id);
    return { title: g.title, notes: own };
  }).filter((g) => g.notes.length);
}

/** Notes of one PDF in print order. */
export function notesForPdf(catalog, key) {
  return pdfSections(catalog, key).flatMap((g) => g.notes);
}

/** Glossary entries of a glossary PDF: of one job (abbreviations in its notes) or all. */
export function glossaryForPdf(catalog, key) {
  const job = pdfJob(key);
  return job ? catalogForJob(catalog, job).glossary : (catalog.glossary ?? []);
}

/** Formulas of a job's formula PDF (the same as on #/formeln for that job). */
export function formulasForPdf(catalog, key) {
  const job = pdfJob(key);
  return job && isFormulasKey(key) ? catalogForJob(catalog, job).formulas : [];
}

/** PDF key for a note's topic in a job: the AP2 PDF if the topic is part of the job's AP2, else AP1. */
export function pdfKeyForTopic(topic, job) {
  if (jobById(job) && topic?.exams?.includes('AP2')) return ap2PdfKey(job);
  if (topic?.exams?.includes('AP1')) return PDF_AP1;
  return jobById(job) ? ap2PdfKey(job) : PDF_ALL;
}

/** "1,2 MB" / "850 KB" for a byte count (German number format). */
export function formatFileSize(bytes) {
  if (!(bytes >= 0)) return '';
  if (bytes < 1000 * 1000) return `${Math.max(1, Math.round(bytes / 1000))} KB`;
  return `${(bytes / 1000 / 1000).toFixed(1).replace('.', ',')} MB`;
}
